package io.aicage.mobile.vpn

import com.facebook.react.ReactPackage
import com.facebook.react.bridge.NativeModule
import com.facebook.react.bridge.ReactApplicationContext
import com.facebook.react.uimanager.ViewManager

/**
 * CageVpnPackage — registers [CageVpnModule] with React Native.
 *
 * This class is referenced in MainApplication.kt (generated by Expo):
 *
 *   override fun getPackages(): List<ReactPackage> = listOf(
 *     ...,
 *     CageVpnPackage()
 *   )
 *
 * Or via the Expo config plugin in src/native/withVpnPermissions.ts
 * which injects this automatically during `expo prebuild`.
 */
class CageVpnPackage : ReactPackage {

    override fun createNativeModules(
        reactContext: ReactApplicationContext,
    ): List<NativeModule> = listOf(
        CageVpnModule(reactContext),
        CageNativeModule(reactContext),
    )

    override fun createViewManagers(
        reactContext: ReactApplicationContext,
    ): List<ViewManager<*, *>> = emptyList()
}
